{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a map of the ruined royal city.",
      "visual_description": "A tired cartographer in an ink-stained coat unrolls a parchment map on a cracked stone table, brass compass spinning, distant broken spires framed against a bruised sky.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of hidden dangers.",
      "visual_description": "An oil lamp with a single glowing eye floats above the map, casting a wary amber light across Mara's furrowed brow.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox returns from a scouting run.",
      "visual_description": "A small clockwork fox with blue glass eyes scampers over rubble, key-wind tail ticking, dragging a torn royal banner in its jaws.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver emerges from a shattered window.",
      "visual_description": "A figure in a clear diving helmet steps from a tall broken pane as if from water, coat reflecting the colored lights of the ruined city.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers at the cracked castle gates.",
      "visual_description": "Two enormous iron gates hang crooked beneath weather-stained royal banners; the Glass Diver, Mara, and Tin Fox stand small before them in dawn fog.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The oracle lamp counts the rhythm of armored patrols.",
      "visual_description": "Shadows of plated boots march along a courtyard wall while the lamp's eye narrows, its flame ticking in time with the footfalls.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Tin Fox slips through a drainage grate.",
      "visual_description": "The clockwork fox squeezes between rusted bars, gears glinting, into a tunnel lit by a thin shaft of green moonlight.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The Glass Diver swims through a tower mirror.",
      "visual_description": "Inside a cursed tower, the diver's coat ripples like water as they pass through a tall silvered mirror, leaving glass petals drifting behind.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "They find the sleeping tax collector at his desk.",
      "visual_description": "A plump official snores facedown on a ledger pillow, stamped papers stuck to his sleeves, ink running like tears across the page.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "Mara questions him, but he only mumbles.",
      "visual_description": "Mara crouches by the desk, compass raised, while the official drools onto a wax seal and waves her off in his sleep.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "The oracle lamp reveals a magic door behind the ledgers.",
      "visual_description": "The lamp's eye blazes, throwing runes across a stack of ledgers that part to show an arched door humming with violet sigils.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "Tin Fox picks the rune lock with its tail key.",
      "visual_description": "The fox stands on its hind legs, key-wind tail turning inside a glowing keyhole, sparks scattering across the threshold.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Inside, rumors of a dragon prove only painted shadows.",
      "visual_description": "A vast hall opens before them, its walls covered in flaking murals of a winged beast; the real chamber is silent, dust motes drifting in lamp-light.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "They find the captive bound in a glass cell.",
      "visual_description": "A frightened figure sits inside a tall glass cylinder; the Glass Diver presses a gloved palm to the surface, ready to swim them out.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "Mara maps an escape route through the back halls.",
      "visual_description": "Mara sketches quickly in the margins of her map, Tin Fox pointing with one paw toward a sliver of corridor marked in red ink.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols close in as alarms wail.",
      "visual_description": "Red lanterns flare along a colonnade; the team sprints past frightened faces peering from boarded windows, the lamp's eye streaking light behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the long bridge out of the city.",
      "visual_description": "A narrow stone bridge arches over a black river; the group runs single file, the sleeping official slung over the Glass Diver's shoulder, papers fluttering loose.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Beyond the bridge, the oracle lamp dims to a soft glow.",
      "visual_description": "On a quiet hilltop at dawn, the rescuers rest among tall grass; the lamp's eye closes to a sleepy spark while Tin Fox curls at Mara's boots.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

